WITH cleaned AS (SELECT *, SUBSTRING(method, 1, 2) AS method_prefix FROM payments WHERE paid_at > TIMESTAMP '2023-11-18 12:00:00'), gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) + INTERVAL '60' DAY THEN 1 ELSE 0 END AS is_new_burst FROM cleaned), sessions_payments AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT CASE WHEN island_id >= 7 THEN 'LARGE' ELSE 'SMALL' END AS island_id_tier, SIZE(COLLECT_SET(status)) AS num_status, SORT_ARRAY(COLLECT_SET(method)) AS method_list, SORT_ARRAY(COLLECT_SET(status)) AS status_list, MAX(paid_at) AS ended_at, MIN(is_new_burst) AS min_is_new_burst, SORT_ARRAY(COLLECT_SET(method)) AS method_list_2 FROM sessions_payments GROUP BY island_id_tier HAVING num_status < 1 ORDER BY min_is_new_burst NULLS LAST;
